// PassportServiceServer is the server API for PassportService service.
// All implementations must embed UnimplementedPassportServiceServer
// for forward compatibility.
//
// 用户通行证（玩家端，只注册在独立的 passport server 上，独立端口，路由就是 /api/v1/...）。
// 账号是独立的 passport_users，与 Momoko 管理后台的用户无关；错误的 message 是错误代码（如 PASSPORT_PASSWORD_INVALID），前端本地化。
type PassportServiceServer interface {
	// 公开配置：注册方式、登录方式、站点名称
	GetPassportConfig(context.Context, *GetPassportConfigRequest) (*GetPassportConfigResponse, error)
	// 发送注册验证码
	SendPassportRegisterCode(context.Context, *SendPassportEmailCodeRequest) (*SendPassportEmailCodeResponse, error)
	// 注册（成功后直接登录）
	PassportRegister(context.Context, *PassportRegisterRequest) (*PassportLoginResponse, error)
	// 发送登录验证码
	SendPassportLoginCode(context.Context, *SendPassportEmailCodeRequest) (*SendPassportEmailCodeResponse, error)
	// 登录：用户名 / 邮箱 + 密码，或邮箱 + 验证码；开启了两步验证时返回 mfa_token，再调 PassportLoginMfa
	PassportLogin(context.Context, *PassportLoginRequest) (*PassportLoginResponse, error)
	// 两步验证：用身份验证器的 6 位验证码或恢复码完成登录
	PassportLoginMfa(context.Context, *PassportLoginMfaRequest) (*PassportLoginResponse, error)
	// 用刷新令牌续期
	PassportRefresh(context.Context, *PassportRefreshRequest) (*PassportLoginResponse, error)
	// 发送找回密码验证码
	SendPassportResetCode(context.Context, *SendPassportEmailCodeRequest) (*SendPassportEmailCodeResponse, error)
	// 用邮箱验证码重设密码（全部设备随之下线）
	PassportResetPassword(context.Context, *PassportResetPasswordRequest) (*PassportEmpty, error)
	// 退出当前设备
	PassportLogout(context.Context, *PassportEmpty) (*PassportEmpty, error)
	// 当前账号：资料、安全状态与计数
	GetPassportMe(context.Context, *PassportEmpty) (*PassportMe, error)
	// 修改资料（昵称、简介、语言、时区、游戏素材头像）
	UpdatePassportProfile(context.Context, *UpdatePassportProfileRequest) (*PassportMe, error)
	// 申请头像直传地址（需要管理员开启头像储存）
	PresignPassportAvatar(context.Context, *PresignPassportAvatarRequest) (*PresignPassportAvatarResponse, error)
	// 直传完成后确认头像
	CompletePassportAvatar(context.Context, *CompletePassportAvatarRequest) (*PassportMe, error)
	// 修改密码（需要当前密码；其他设备随之下线）
	ChangePassportPassword(context.Context, *ChangePassportPasswordRequest) (*PassportEmpty, error)
	// 发送更换邮箱的验证码（发到新邮箱）
	SendPassportEmailChangeCode(context.Context, *SendPassportEmailCodeRequest) (*SendPassportEmailCodeResponse, error)
	// 更换 / 绑定邮箱
	ChangePassportEmail(context.Context, *ChangePassportEmailRequest) (*PassportMe, error)
	// 开关邮箱验证码登录
	SetPassportEmailLogin(context.Context, *SetPassportEmailLoginRequest) (*PassportMe, error)
	// 开始设置两步验证：生成密钥与二维码（确认前不生效）
	SetupPassportTotp(context.Context, *PassportEmpty) (*SetupPassportTotpResponse, error)
	// 输入身份验证器的验证码确认开启，返回恢复码（只显示这一次）
	EnablePassportTotp(context.Context, *EnablePassportTotpRequest) (*PassportRecoveryCodes, error)
	// 关闭两步验证（需要密码与验证码）
	DisablePassportTotp(context.Context, *DisablePassportTotpRequest) (*PassportMe, error)
	// 重新生成恢复码（需要验证码；旧恢复码作废）
	RegeneratePassportRecoveryCodes(context.Context, *PassportTotpCodeRequest) (*PassportRecoveryCodes, error)
	// 登录设备
	ListPassportDevices(context.Context, *PassportEmpty) (*ListPassportDevicesResponse, error)
	// 让某台设备下线
	RevokePassportDevice(context.Context, *RevokePassportDeviceRequest) (*PassportEmpty, error)
	// 退出其他所有设备
	LogoutPassportOthers(context.Context, *PassportEmpty) (*PassportEmpty, error)
	// 授权的应用（用「用户通行证登录」登录过的游戏与应用）
	ListPassportApps(context.Context, *PassportEmpty) (*ListPassportAppsResponse, error)
	// 撤销授权（已签发的访问令牌随之失效，下次需要重新确认）
	RevokePassportApp(context.Context, *RevokePassportAppRequest) (*PassportEmpty, error)
	// 申请注销（7 天后删除，期间可撤销）
	RequestPassportDeletion(context.Context, *RequestPassportDeletionRequest) (*PassportMe, error)
	// 撤销注销申请
	CancelPassportDeletion(context.Context, *PassportEmpty) (*PassportMe, error)
	// 消息
	ListPassportMessages(context.Context, *ListPassportMessagesRequest) (*ListPassportMessagesResponse, error)
	// 标记已读（all 为全部）
	ReadPassportMessages(context.Context, *ReadPassportMessagesRequest) (*ReadPassportMessagesResponse, error)
	// 最近活动：登录、绑定与解绑、自助操作、兑换码（都来自真实记录）
	ListPassportActivity(context.Context, *ListPassportActivityRequest) (*ListPassportActivityResponse, error)
	// 我绑定的游戏账号（按游戏分组展示）
	ListPassportLinks(context.Context, *PassportEmpty) (*ListPassportLinksResponse, error)
	// 设为这款游戏的常用账号
	SetPassportPrimaryLink(context.Context, *PassportLinkRequest) (*PassportEmpty, error)
	// 解绑（解绑后 7 天内不能在同一服务器绑定别的账号）
	UnbindPassportLink(context.Context, *PassportLinkRequest) (*PassportEmpty, error)
	// 绑定时选服务器：搜索（名称或邀请码，最多 20 条）+ 推荐（最多 5 个公开服务器）
	SearchPassportBindServers(context.Context, *SearchPassportBindServersRequest) (*SearchPassportBindServersResponse, error)
	// 用游戏账号 + 密码绑定（游戏服务端 MGP /accounts/verify 校验，密码不保存）
	BindPassportAccount(context.Context, *BindPassportAccountRequest) (*PassportLink, error)
	// 游戏空间：服务器、绑定、manifest 中玩家端用到的部分、玩家摘要；同时记录 last_seen_at
	GetPassportGame(context.Context, *PassportGameRequest) (*PassportGameResponse, error)
	// 首页卡片用的摘要（玩家摘要，刷新绑定快照；不记录 last_seen_at）
	GetPassportGameBrief(context.Context, *PassportGameRequest) (*PassportGameResponse, error)
	// 自己的分页数据（MGP /players/{我的 pid}/views/{view}）
	GetPassportGameView(context.Context, *PassportGameViewRequest) (*PassportDataResponse, error)
	// 选择器数据（MGP /catalogs/{kind}，名称与素材 ID；每次最多 50 条）
	GetPassportGameCatalog(context.Context, *PassportGameCatalogRequest) (*PassportDataResponse, error)
	// 正在进行的卡池（只含 id、名称、横幅素材与起止时间）
	ListPassportGameOngoing(context.Context, *PassportGameRequest) (*PassportDataResponse, error)
	// 自助服务：已开放的指令与我的使用情况
	ListPassportSelfService(context.Context, *PassportGameRequest) (*ListPassportSelfServiceResponse, error)
	// 执行一条自助指令（目标强制为我绑定的游戏账号；需要审批的只提交申请）
	ExecutePassportSelfService(context.Context, *ExecutePassportSelfServiceRequest) (*ExecutePassportSelfServiceResponse, error)
	// 我的申请（需要审批的自助指令）
	ListPassportGameRequests(context.Context, *ListPassportGameRecordsRequest) (*ListPassportGameRecordsResponse, error)
	// 操作记录（我在这台服务器上的自助操作与兑换码）
	ListPassportGameRecords(context.Context, *ListPassportGameRecordsRequest) (*ListPassportGameRecordsResponse, error)
	// 兑换码（奖励进礼物箱）
	RedeemPassportGiftCode(context.Context, *RedeemPassportGiftCodeRequest) (*RedeemPassportGiftCodeResponse, error)
	// 授权确认页：校验请求并返回应用信息（已授权过且范围不变时 granted=true）
	GetPassportOidcAuthorization(context.Context, *PassportOidcAuthorizeRequest) (*PassportOidcAuthorizationInfo, error)
	// 同意授权：生成授权码，返回应用的回调地址
	ApprovePassportOidcAuthorization(context.Context, *PassportOidcAuthorizeRequest) (*PassportOidcAuthorizeResponse, error)
	mustEmbedUnimplementedPassportServiceServer()
}

